@inproceedings{mathys_synthetic_2025,
  title = {Synthetic {{Data}} for {{Blood Vessel Network Extraction}}},
  booktitle = {Will {{Synthetic Data Finally Solve}} the {{Data Access Problem}}?},
  author = {Mathys, Jo{\"e}l and Plesner, Andreas and Elmiger, Jorel and Wattenhofer, Roger},
  year = 2025,
  month = mar,
  abstract = {Blood vessel networks in the brain play a crucial role in stroke research, where understanding their topology is essential for analyzing blood flow dynamics. However, extracting detailed topological vessel network information from microscopy data remains a significant challenge, mainly due to the scarcity of labeled training data and the need for high topological accuracy. This work combines synthetic data generation with deep learning to automatically extract vessel networks as graphs from volumetric microscopy data. To combat data scarcity, we introduce a comprehensive pipeline for generating large-scale synthetic datasets that mirror the characteristics of real vessel networks. Our three-stage approach progresses from abstract graph generation through vessel mask creation to realistic medical image synthesis, incorporating biological constraints and imaging artifacts at each stage. Using this synthetic data, we develop a two-stage deep learning pipeline of 3D U-Net-based models for node detection and edge prediction. Fine-tuning on real microscopy data shows promising adaptation, improving edge prediction F1 scores from 0.496 to 0.626 by training on merely 5 manually labeled samples. These results suggest that automated vessel network extraction is becoming practically feasible, opening new possibilities for large-scale vascular analysis in stroke research.},
  langid = {english}
}

@inproceedings{grotschla_reinforcement_2025,
  title = {Reinforcement {{Learning}} for {{Locally Checkable Labeling Problems}}},
  booktitle = {The {{Seventeenth Workshop}} on {{Adaptive}} and {{Learning Agents}}},
  author = {Gr{\"o}tschla, Florian and Mathys, Jo{\"e}l and Holbein, Lo{\"i}c and Wattenhofer, Roger},
  year = 2025,
  month = apr,
  abstract = {We address the challenge of solving locally checkable labeling (LCL) problems on graphs using machine learning. Unlike prior supervised approaches that depend on ground-truth algorithms or enforce unique solutions, we propose a reinforcement learning framework that requires only verifiers to evaluate correctness. This formulation allows models to learn solution strategies independently, without bias toward specific algorithmic procedures, and inherently supports the discovery of non-unique solutions. We evaluate our method on four fundamental LCL problems, demonstrating its ability to generalize effectively, outperform supervised baselines, and provide a versatile foundation for learning algorithmic reasoning on graphs.},
  langid = {english}
}

@inproceedings{grillo_interpolation_2024,
  title = {Beyond {{Interpolation}}: {{Extrapolative Reasoning}} with {{Reinforcement Learning}} and {{Graph Neural Networks}}},
  shorttitle = {Beyond {{Interpolation}}},
  booktitle = {The {{First Workshop}} on {{Neural Reasoning}} and {{Mathematical Discovery}} at {{AAAI}}'2025},
  author = {Grillo, Niccol{\`o} and Toccaceli, Andrea and Mathys, Jo{\"e}l and Estermann, Benjamin and Fresca, Stefania and Wattenhofer, Roger},
  year = 2024,
  month = dec,
  abstract = {Despite incredible progress, many neural architectures fail to properly generalize beyond their training distribution. As such, learning to reason in a correct and generalizable way is one of the current fundamental challenges in machine learning. In this respect, logic puzzles provide a great testbed, as we can fully understand and control the learning environment. Thus, they allow to evaluate performance on previously unseen, larger and more difficult puzzles that follow the same underlying rules. Since traditional approaches often struggle to represent such scalable logical structures, we propose to model these puzzles using a graph-based approach. Then, we investigate the key factors enabling the proposed models to learn generalizable solutions in a reinforcement learning setting. Our study focuses on the impact of the inductive bias of the architecture, different reward systems and the role of recurrent modeling in enabling sequential reasoning. Through extensive experiments, we demonstrate how these elements contribute to successful extrapolation on increasingly complex puzzles. These insights and frameworks offer a systematic way to design learning-based systems capable of generalizable reasoning beyond interpolation.},
  langid = {english}
}

@inproceedings{mathys_rethinking_2025,
  title = {Rethinking {{Message Passing}} for {{Algorithmic Alignment}}},
  booktitle = {{{NeurIPS}} 2024 {{Workshop}} on {{Symmetry}} and {{Geometry}} in {{Neural Representations}}},
  author = {Mathys, Jo{\"e}l and Gr{\"o}tschla, Florian and Nadimpalli, Kalyan Varma and Wattenhofer, Roger},
  year = 2025,
  month = feb,
  abstract = {Most Graph Neural Networks are based on the principle of message-passing, where all neighboring nodes exchange messages with each other simultaneously. We want to challenge this paradigm by introducing the Flood and Echo Net, a novel architecture that aligns neural computation with the principles of distributed algorithms. In our method, nodes sparsely activate upon receiving a message, leading to a wave-like activation pattern that traverses the graph. Through these sparse but parallel activations, the Net becomes more expressive than traditional MPNNs which are limited by the 1-WL test and also is provably more efficient in terms of message complexity. Moreover, the mechanism's ability to generalize across graphs of varying sizes positions it as a practical architecture for the task of algorithmic learning. We test the Flood and Echo Net on a variety of synthetic tasks and find that the algorithmic alignment of the execution improves generalization to larger graph sizes.},
  langid = {english}
}

@inproceedings{mathys_new_2025a,
  title = {A {{New Perspective}} for {{Graph Learning Architecture Design}}: {{Linearize Your Depth Away}}},
  shorttitle = {A {{New Perspective}} for {{Graph Learning Architecture Design}}},
  booktitle = {New {{Perspectives}} in {{Graph Machine Learning}}},
  author = {Mathys, Jo{\"e}l and Wattenhofer, Roger},
  year = 2025,
  month = oct,
  abstract = {Designing effective graph learning architectures is central to making learning on structured and relational data feasible and scalable. Crucially, such designs must incorporate sufficient inductive bias to capture and leverage the graph topology. Simultaneously, they have to balance this objective with efficiently utilizing modern hardware, and remaining effectively trainable, even at scale. The current proposed architectures and paradigms range from message-passing neural networks on the graph topology to graph-informed transformers and virtual compute structures. Especially, the latter techniques often translate useful concepts and insights from graph theory in order to improve stability, mixing time, or bottlenecks. In this work, we highlight a linearization technique from the recently proposed Graph State-Space Model, as a powerful, general tool to design or improve graph learning architectures. At its core, the technique simplifies and reduces sequential computational depth and improves execution speed, while largely preserving trainability. Furthermore, the tool is versatile enough to be applied as a drop-in module across existing architectures. We showcase this flexibility by adapting Cayley Graph Propagation, yielding a simple, deeper and faster architecture.},
  langid = {english}
}

@inproceedings{grotschla_coregd_2023,
  title = {{{CoRe-GD}}: {{A Hierarchical Framework}} for {{Scalable Graph Visualization}} with {{GNNs}}},
  shorttitle = {{{CoRe-GD}}},
  booktitle = {The {{Twelfth International Conference}} on {{Learning Representations}}},
  author = {Gr{\"o}tschla, Florian and Mathys, Jo{\"e}l and Veres, Robert and Wattenhofer, Roger},
  year = 2023,
  month = oct,
  abstract = {Graph Visualization, also known as Graph Drawing, aims to find geometric embeddings of graphs that optimize certain criteria. Stress is a widely used metric; stress is minimized when every pair of nodes is positioned at their shortest path distance. However, stress optimization presents computational challenges due to its inherent complexity and is usually solved using heuristics in practice. We introduce a scalable Graph Neural Network (GNN) based Graph Drawing framework with sub-quadratic runtime that can learn to optimize stress. Inspired by classical stress optimization techniques and force-directed layout algorithms, we create a coarsening hierarchy for the input graph. Beginning at the coarsest level, we iteratively refine and un-coarsen the layout, until we generate an embedding for the original graph. To enhance information propagation within the network, we propose a novel positional rewiring technique based on intermediate node positions. Our empirical evaluation demonstrates that the framework achieves state-of-the-art performance while remaining scalable.},
  langid = {english}
}

@inproceedings{mathys_lrim_2026,
  title = {{{LRIM}}: A {{Physics-Based Benchmark}} for {{Provably Evaluating Long-Range Capabilities}} in {{Graph Learning}}},
  shorttitle = {{{LRIM}}},
  booktitle = {The {{Fourteenth International Conference}} on {{Learning Representations}}},
  author = {Mathys, Jo{\"e}l and Christiansen, Henrik and Errica, Federico and Maruyama, Takashi and Alesiani, Francesco},
  year = 2026,
  month = apr,
  abstract = {Accurately modeling long-range dependencies in graph-structured data is critical for many real-world applications. However, incorporating long-range interactions beyond the nodes' immediate neighborhood in a \$\textbackslash textit\textbraceleft scalable\textbraceright\$ manner remains an open challenge for graph machine learning models. Existing benchmarks for evaluating long-range capabilities either cannot \$\textbackslash textit\textbraceleft guarantee\textbraceright\$ that their tasks actually depend on long-range information or are rather limited. Therefore, claims of long-range modeling improvements based on said performance remain questionable. We introduce the Long-Range Ising Model Graph Benchmark, a physics-based benchmark utilizing the well-studied Ising model whose ground truth \$\textbackslash textit\textbraceleft provably\textbraceright\$ depends on long-range dependencies. Our benchmark consists of ten datasets that scale from 256 to 65k nodes per graph, and provide controllable long-range dependencies through tunable parameters, allowing precise control over the hardness and ``long-rangedness". We provide model-agnostic evidence that local information is insufficient, further validating the design choices of our benchmark. Via experiments on classical message-passing architectures and graph transformers, we show that both perform far from the optimum, especially those with scalable complexity. Our goal is that our benchmark will foster the development of scalable methodologies that effectively model long-range interactions in graphs.},
  langid = {english}
}

@inproceedings{minder_salsaclrs_2023,
  title = {{{SALSA-CLRS}}: {{A Sparse}} and {{Scalable Benchmark}} for {{Algorithmic Reasoning}}},
  shorttitle = {{{SALSA-CLRS}}},
  booktitle = {The {{Second Learning}} on {{Graphs Conference}}},
  author = {Minder, Julian and Gr{\"o}tschla, Florian and Mathys, Jo{\"e}l and Wattenhofer, Roger},
  year = 2023,
  month = nov,
  abstract = {We introduce an extension to the CLRS algorithmic learning benchmark, prioritizing scalability and the utilization of sparse representations. Many algorithms in CLRS require global memory or information exchange, mirrored in its execution model, which constructs fully connected graphs (not sparse) based on the underlying problem. Despite CLRS's aim of assessing how effectively learned algorithms can generalize to larger instances, the existing execution model becomes a significant constraint due to its demanding memory requirements and runtime (hard to scale). Simultaneously, certain algorithms do not demand a fully connected graph; these algorithms, primarily distributed in nature, align closely with the message-passing paradigm employed by Graph Neural Networks. Hence, we propose SALSA-CLRS, an extension of the current CLRS benchmark specifically with scalability and sparseness in mind. Our approach includes adapted algorithms from the original CLRS benchmark and introduces new problems from distributed and randomized algorithms. Moreover, we perform a thorough empirical evaluation of our benchmark. Code is publicly available at https://github.com/jkminder/salsa-clrs.},
  langid = {english}
}
